1: // Define a function to sort the shopping cart using recursion
2: void sortCart(std::vector<std::string>& cart) {
3:     if (cart.size() <= 1) {
4:         return;
5:     }
6:     std::string pivot = cart[0];
7:     std::vector<std::string> left, middle, right;
8:     for (std::vector<std::string>::iterator it = cart.begin() + 1; it != cart.end(); ) {
9:         if (*it < pivot) {
10:             left.push_back(*it);
11:             cart.erase(it++);
12:         } else if (*it == pivot) {
13:             middle.push_back(*it);
14:             cart.erase(it++);
15:         } else {
16:             right.push_back(*it);
17:             cart.erase(it++);
18:         }
19:     }
20:     sortCart(left);
21:     sortCart(right);
22:     cart.insert(cart.begin(), left.begin(), left.end());
23:     cart.insert(cart.begin() + left.size(), middle.begin(), middle.end());
24:     cart.insert(cart.begin() + left.size() + middle.size(), right.begin(), right.end());
25: }
26: // Example usage:
27: int main() {
28:     std::vector<std::string> cart = {"apple", "banana", "cherry", "date", "elderberry"};
29:     sortCart(cart);
30:     for (const auto& item : cart) {
31:         std::cout << item << " ";
32:     }
33:     return 0;
34: }

